#define COLOR3 vec3(0.988, 0.914, 0.812) // #FCE9CF
#define COLOR2 vec3(0.361, 0.812, 0.565) // #5CCF90
#define COLOR4 vec3(0.514, 0.933, 0.757) // #83EEC1
#define COLOR1 vec3(0.875, 0.949, 0.910) // #DFF2E8

float rand(vec2 p) {
    return fract(sin(dot(p, vec2(12.99, 78.233))) * 43758.545);
}

float noise(vec2 p) {
    vec2 f = fract(p);
    f = f * f * (3. - 2. * f);
    vec2 i = floor(p);
    return mix(mix(rand(i + vec2(0, 0)), 
                   rand(i + vec2(1, 0)), f.x),
               mix(rand(i + vec2(0, 1)), 
                   rand(i + vec2(1, 1)), f.x), f.y);
}

float fbm(vec2 p) {
    float v = 0.;
    float a = 0.5;
    mat2 rot = mat2(cos(0.5), sin(0.5), -sin(0.5), cos(0.5));
    for(int i = 0; i < 6; ++i) {
        v += a * noise(p);
        p = rot * p * 2.0 + vec2(1.7, 9.2);
        a *= 0.5;
    }
    return v;
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = fragCoord.xy / iResolution.xy;
    vec2 p = (2.0 * fragCoord - iResolution.xy) / min(iResolution.x, iResolution.y);

    float time = iTime * 0.1;

    float f = fbm(p * 3.0 + time);
    float f2 = fbm(p * 5.0 - time * 0.5 + f);

    vec2 q = vec2(f, f2);

    float final = fbm(p * 2.0 + q * 8.0);

    vec3 col = mix(COLOR1, COLOR2, smoothstep(0.0, 0.6, final));
    col = mix(col, COLOR3, smoothstep(0.3, 1.0, final));
    col = mix(col, COLOR4, smoothstep(0.6, 1.0, final));

    col = pow(col, vec3(1.9)); // Brightness
    col = mix(col, col * col * (3.0 - 2.0 * col), 0.2); // Saturation

    // Add subtle highlights instead of shadows
    float highlight = smoothstep(0.5, 0.9, noise(p * 10.0 + time * 2.0));
    col += highlight * 0.1 * COLOR4; // Highlights


    fragColor = vec4(col, 1.0);
}
